{"content":"from sage.all import *

def r(G,u,v):
 ns=list(G);ns.remove(v)
 L=G.kirchhoff_matrix(vertices=ns+[v])[:-1,:-1]
 return L.inverse()[ns.index(u),ns.index(u)]
for d in [3,5,7,9,11,13]:
 m=d+2
 G=graphs.CompleteGraph(m)
 G.delete_edge(0,1);G.delete_edge(0,2)
 for i in range(3,m,2):G.delete_edge(i,i+1)
 print('odd d',d,'end size',m,'terminal R',max(r(G,0,v) for v in range(1,m)), 'min order commute',2*m*d*(1+2*max(r(G,0,v) for v in range(1,m))))
for d in [4,6,8,10]:
 # clique core size d, split extra vertex into ports degrees 2 and d-2
 G=graphs.CompleteGraph(d)
 G.add_vertices([d,d+1])
 for i in range(d):G.add_edge(i,d if i<2 else d+1)
 print('even d',d,'internal order',d+2,'R',r(G,d,d+1))
