from sage.all import *
import time,pickle,os

def max_commute(G):
 n=G.order(); d=G.degree(0)
 if not G.is_connected():return None
 L=G.kirchhoff_matrix()[:-1,:-1].inverse()
 rs=[L[i,i] for i in range(n-1)]+[L[i,i]+L[j,j]-2*L[i,j] for i in range(n-1) for j in range(i)]
 return n*d*max(rs)
start=time.time()
for n in [8,10]:
 for d in range(2,(n-1)//2+1):
  key=f'reg_{n}_{d}.pkl'
  if os.path.exists(key):
   gs=pickle.load(open(key,'rb'))
  else:
   gs=[G.graph6_string() for G in graphs(n,degree_sequence=[d]*n)]
   pickle.dump(gs,open(key,'wb'))
  b1=(-1,None);b2=(-1,None)
  for st in gs:
   G=Graph(st)
   a=max_commute(G)
   if a is not None and a>b1[0]:b1=(a,st)
   a=max_commute(G.complement())
   if a is not None and a>b2[0]:b2=(a,st)
  print(n,d,len(gs),'best',b1,'complement best',b2,'time',time.time()-start,flush=True)

